def pasar_a_partidas(apps, schema_editor):
    """Cada apartado viejo (una prenda y una cantidad) se convierte en una partida del pedido nuevo."""
    Apartado = apps.get_model("tienda", "Apartado")
    ApartadoItem = apps.get_model("tienda", "ApartadoItem")
    for ap in Apartado.objects.all():
        ApartadoItem.objects.create(
            apartado=ap,
            prenda_id=ap.prenda_id,
            cantidad=ap.cantidad,
            de_inventario=ap.cantidad if ap.tipo == "INVENTARIO" else 0,
            precio_unitario=ap.total / ap.cantidad,
        )


def volver_a_una_prenda(apps, schema_editor):
    """Reversa: solo es posible para pedidos de una sola partida."""
    Apartado = apps.get_model("tienda", "Apartado")
    ApartadoItem = apps.get_model("tienda", "ApartadoItem")
    for ap in Apartado.objects.all():
        item = ApartadoItem.objects.filter(apartado=ap).first()
        if item:
            ap.prenda_id, ap.cantidad = item.prenda_id, item.cantidad
            ap.tipo = "INVENTARIO" if item.de_inventario else "ESPECIAL"
            ap.save()


